<?php
namespace Junior\Serverside; class Request { const JSON_RPC_VERSION = "2.0"; const ERROR_PARSE_ERROR = -32700; const ERROR_INVALID_REQUEST = -32600; const ERROR_MISMATCHED_VERSION = -32000; const ERROR_RESERVED_PREFIX = -32001; const VALID_FUNCTION_NAME = '/^[a-zA-Z_][a-zA-Z0-9_]*$/'; public $batch; public $raw; public $result; public $json_rpc; public $error_code; public $error_message; public $method; public $params; public $id; public $exception; public function __construct($json) { $this->batch = false; $this->raw = $json; if ($this->raw === "") { $this->json_rpc = self::JSON_RPC_VERSION; $this->error_code = self::ERROR_INVALID_REQUEST; $this->error_message = "Пустой JSON-RPC запрос."; return; } $patterns = array(); $patterns[0] = '<'; $patterns[1] = '>'; $replacements = array(); $replacements[0] = '('; $replacements[1] = ')'; $json = str_replace($patterns, $replacements, $json); $obj = safe_json_decode($json); if ($obj === null) { $this->json_rpc = self::JSON_RPC_VERSION; $this->error_code = self::ERROR_PARSE_ERROR; $this->error_message = "Ошибка разбора JSON-RPC запроса (".json_last_error()."): ".$json; return; } if (is_array($obj)) { if (count($obj) == 0) { $this->json_rpc = self::JSON_RPC_VERSION; $this->error_code = self::ERROR_INVALID_REQUEST; $this->error_message = "Пустой пакетный JSON-RPC запрос."; return; } $this->batch = true; $this->requests = array(); foreach ($obj as $req) { if (!is_object($req)) { $this->requests[] = new Request(''); } else { $this->requests[] = new Request(json_encode($req, JSON_UNESCAPED_UNICODE)); } } } else { $this->json_rpc = $obj->jsonrpc; $this->method = $obj->method; if (property_exists($obj,'params')) { $this->params = $obj->params; } if (property_exists($obj,'id')) { $this->id = $obj->id; } } } public function checkValid() { if ($this->error_code && $this->error_message) { return false; } if (!$this->json_rpc) { $this->error_code = self::ERROR_INVALID_REQUEST; $this->error_message = "В запросе не указана версия JSON-RPC."; return false; } if (!$this->method) { $this->error_code = self::ERROR_INVALID_REQUEST; $this->error_message = "В запросе JSON-RPC не указано название метода."; return false; } if (substr($this->method, 0, 4) == 'rpc.') { $this->error_code = self::ERROR_RESERVED_PREFIX; $this->error_message = "В запросе JSON-RPC неверное название метода; Метод не может начинаться с 'rpc.'."; return false; } if (!preg_match(self::VALID_FUNCTION_NAME, $this->method)) { $this->error_code = self::ERROR_INVALID_REQUEST; $this->error_message = "В запросе JSON-RPC неправильное название метода."; return false; } if ($this->json_rpc != "2.0") { $this->error_code = self::ERROR_MISMATCHED_VERSION; $this->error_message = "Неверная версия JSON-RPC; Ожидаемая '2.0'."; return false; } return true; } public function isBatch() { return $this->batch; } public function isNotify() { return !isset($this->id); } public function toResponseJSON() { global $jsonRpcExceptionNoDebug; $response = new \stdClass; $response->jsonrpc = '2.0'; $response->id = $this->id; if ($this->error_code || $this->error_message || $this->exception) { if (isset($this->exception) && isset($this->exception->jsonRpcError)) { $response->error = $this->exception->jsonRpcError; } else { $error = new \stdClass; $error->code = $this->error_code; $error->message = $this->error_message; if (isset($this->exception)) { $e = decorateException($this->exception); $error->code = $e->getCode(); $error->message = $e->getMessage(); if (!$jsonRpcExceptionNoDebug) { $error->debug = $debug = new \stdClass; $debug->file = $e->getFile().'('.$e->getLine().')'; $debug->line = $e->getLine(); $debug->trace = $e->getTraceAsString(); $previous = $e->getPrevious(); if ($previous) { $debug->previous = exceptionToJsonRpcError($previous); } } } $response->error = $error; } error_log("JSON-RPC ERROR: ".print_r($response, true)); } else { $response->result = $this->result; } return json_encode($response, JSON_UNESCAPED_UNICODE); } }